import csv
import html
import json
import re
import unicodedata
from pathlib import Path


TASK_DIR = Path(__file__).resolve().parent
PACKAGE_DIR = TASK_DIR.parents[2] / "event_packages" / "standard_event_packages" / "packages" / "CSX-179"
OUTPUT_PATH = TASK_DIR / "computed_gt.json"

HIDDEN_INPUTS = [
    "data/event_reports/event_reports_004_Locked_anchor_report_NASA_Earth_Observatory.html",
    "data/event_reports/event_reports_003_Locked_event_anchor_2015_Southeast_Asia_haze_from_Indonesian_fires.json",
    "data/remote_sensing/remote_sensing_001_pre.jpg",
    "data/remote_sensing/remote_sensing_002_event.jpg",
    "data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json",
    "data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json",
    "data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json",
    "data/physical_hazard/physical_hazard_001_Open-Meteo_daily_weather_fill.json",
    "metadata/files.csv",
]


def read_json(relative_path):
    with (PACKAGE_DIR / relative_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_text(relative_path):
    return (PACKAGE_DIR / relative_path).read_text(encoding="utf-8", errors="replace")


def strip_html(raw_html):
    text = re.sub(r"<script\b.*?</script>", " ", raw_html, flags=re.I | re.S)
    text = re.sub(r"<style\b.*?</style>", " ", text, flags=re.I | re.S)
    text = re.sub(r"<[^>]+>", " ", text)
    text = html.unescape(text)
    return re.sub(r"\s+", " ", text).strip()


def ascii_fold(text):
    return unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode("ascii")


def first_int(pattern, text, name):
    match = re.search(pattern, text, flags=re.I)
    if not match:
        raise ValueError(f"Could not find {name}")
    return int(match.group(1).replace(",", ""))


def precipitation_open_meteo_event_total():
    data = read_json("data/physical_hazard/physical_hazard_001_Open-Meteo_daily_weather_fill.json")
    dates = data["daily"]["time"]
    precip = data["daily"]["precipitation_sum"]
    values = [
        value
        for date, value in zip(dates, precip)
        if "2015-08-01" <= date <= "2015-09-15"
    ]
    return round(sum(values), 6)


def remote_sensing_manifest():
    rows = []
    with (PACKAGE_DIR / "metadata" / "files.csv").open("r", encoding="utf-8", newline="") as handle:
        for row in csv.DictReader(handle):
            if row["data_category"] == "remote_sensing":
                rows.append(row)

    parsed = {}
    for row in rows:
        url = row["url"]
        time_match = re.search(r"[?&]TIME=([0-9-]+)", url)
        width_match = re.search(r"[?&]WIDTH=([0-9]+)", url)
        height_match = re.search(r"[?&]HEIGHT=([0-9]+)", url)
        layer_match = re.search(r"[?&]LAYERS=([^&]+)", url)
        parsed[row["source_name"]] = {
            "relative_path": row["relative_path"],
            "date": time_match.group(1) if time_match else None,
            "width_px": int(width_match.group(1)) if width_match else None,
            "height_px": int(height_match.group(1)) if height_match else None,
            "layer": layer_match.group(1) if layer_match else None,
        }
    return parsed


def build_rubric():
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "Classification and JSON shape",
                "points": 3,
                "description": "Gives peat_smoke_co_signal and returns the requested compact JSON fields.",
                "partial_credit": "Award 1-2 points for the right classification with missing fields, or a parseable ledger with a weaker but related label.",
            },
            {
                "name": "Carbon monoxide arithmetic",
                "points": 4,
                "description": "Reports about 100 ppb usual CO, nearly 1,300 ppb peak surface CO, and the 13.0x multiplier.",
                "partial_credit": "Award 1-3 points for two correct values, a correct formula with a rounding issue, or correct units with one missing CO anchor.",
            },
            {
                "name": "Vertical transport ledger",
                "points": 4,
                "description": "Reports 2 km, 5 km, 9 km, and the 4.5 MLS-to-CALIPSO ratio.",
                "partial_credit": "Award 1-3 points for most heights with a missing ratio or one swapped/misrounded value.",
            },
            {
                "name": "Context checks",
                "points": 3,
                "description": "Marks available package rainfall diagnostics as secondary and marks the dNBR burn-perimeter test as not_established because pre and post counts are both zero.",
                "partial_credit": "Award 1-2 points for getting one check right or giving the right conclusion without the scene-count reason.",
            },
            {
                "name": "Image-to-number synthesis",
                "points": 3,
                "description": "Connects the 2015-09-30 true-color haze view to the CO ledger while keeping the 2015-07-02 image as the pre-event comparison.",
                "partial_credit": "Award 1-2 points for mentioning haze imagery without dates or without linking it to the CO values.",
            },
            {
                "name": "Compact computed interpretation",
                "points": 3,
                "description": "Keeps the final sentence tied to peat-smoke gas loading and avoids realized-loss counts, action steps, and broad policy claims.",
                "partial_credit": "Award 1-2 points for a mostly ledger-based interpretation with minor extra narrative.",
            },
        ],
    }


def main():
    report_html = read_text(HIDDEN_INPUTS[0])
    report_text = strip_html(report_html)
    folded_text = ascii_fold(report_text)
    folded_html = ascii_fold(report_html)

    event_anchor = read_json(HIDDEN_INPUTS[1])
    dnbr = read_json("data/physical_hazard/physical_hazard_009_Sentinel-2_SR_Harmonized_dNBR.json")
    gpm = read_json("data/physical_hazard/physical_hazard_005_GPM_IMERG_V07_event_accumulated_precipitation.json")
    chirps = read_json("data/physical_hazard/physical_hazard_007_CHIRPS_daily_event_accumulated_precipitation.json")
    era5 = read_json("data/physical_hazard/physical_hazard_003_ERA5-Land_hourly_aggregate_stats.json")

    usual_co_ppb = first_int(
        r"usually about ([0-9,]+) parts per billion",
        folded_text,
        "usual carbon monoxide",
    )
    peak_co_ppb = first_int(
        r"up to nearly ([0-9,]+) parts per billion",
        folded_text,
        "peak carbon monoxide",
    )
    calipso_plume_km = first_int(
        r"reached ([0-9]+) kilometers?",
        folded_text,
        "CALIPSO plume height",
    )
    airs_co_km = first_int(
        r"about ([0-9]+) kilometers above the surface",
        folded_text,
        "AIRS carbon monoxide height",
    )
    mls_co_km = first_int(
        r"upwards of ([0-9]+) kilometers",
        folded_text,
        "MLS carbon monoxide height",
    )

    co_multiplier = round(peak_co_ppb / usual_co_ppb, 1)
    height_ratio = round(mls_co_km / calipso_plume_km, 1)
    open_meteo_total = precipitation_open_meteo_event_total()
    remote_sensing = remote_sensing_manifest()

    rain_context = {
        "gpm_mean": round(gpm["stats"]["gpm_event_precip_mm_mean"], 3),
        "chirps_mean": round(chirps["stats"]["chirps_event_precip_mm_mean"], 3),
        "era5_mean": round(era5["stats"]["precipitation_sum_mm_mean"], 3),
        "open_meteo_total": round(open_meteo_total, 3),
    }

    primary_gt = {
        "classification": "peat_smoke_co_signal",
        "co_signal": {
            "usual_surface_ppb": usual_co_ppb,
            "peak_surface_borneo_ppb_nearly": peak_co_ppb,
            "peak_to_usual_multiplier": co_multiplier,
        },
        "vertical_transport": {
            "calipso_plume_km": calipso_plume_km,
            "airs_co_km": airs_co_km,
            "mls_co_km": mls_co_km,
            "mls_to_calipso_ratio": height_ratio,
        },
        "context_checks": {
            "rainfall_totals_secondary": True,
            "burn_perimeter_from_dnbr": "not_established",
        },
        "image_reading": (
            "The 2015-09-30 true-color view is consistent with a broad gray haze layer compared with "
            "the 2015-07-02 pre-event view."
        ),
        "computed_interpretation": (
            "The decisive ledger is peat-smoke gas loading: near-surface CO rose to about thirteen times "
            "the usual value and was also detected several kilometers above the surface."
        ),
    }

    computed = {
        "schema_version": "1.0",
        "task_id": "CSX-179_Q2",
        "event_id": "CSX-179",
        "task_type": "short_answer",
        "target_family": "peat_smoke_co_signal_ledger",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "numeric_tolerances": {
            "usual_surface_ppb": {"value": usual_co_ppb, "tolerance": 0},
            "peak_surface_borneo_ppb_nearly": {"value": peak_co_ppb, "tolerance": 50},
            "peak_to_usual_multiplier": {"value": co_multiplier, "tolerance": 0.1},
            "calipso_plume_km": {"value": calipso_plume_km, "tolerance": 0.2},
            "airs_co_km": {"value": airs_co_km, "tolerance": 0.5},
            "mls_co_km": {"value": mls_co_km, "tolerance": 1.0},
            "mls_to_calipso_ratio": {"value": height_ratio, "tolerance": 0.1},
        },
        "judge_anchors": {
            "canonical_stance": "The decisive ledger is a peat-smoke carbon monoxide signal, not a rainfall-total anomaly or burn-perimeter answer.",
            "required_elements": [
                "Return peat_smoke_co_signal as the classification.",
                "Compute 1300 / 100 = 13.0 for the CO multiplier.",
                "Use 2 km, 5 km, 9 km, and 4.5 for the vertical ledger.",
                "Treat rainfall totals and dNBR scene counts as secondary context checks.",
                "Keep the final interpretation tied to the requested ledger.",
            ],
            "avoid": [
                "realized mortality, hospitalization, or economic-loss totals",
                "broad policy advice or action steps",
                "a complete burn-perimeter conclusion from the dNBR counts",
            ],
        },
        "key_values": {
            "event": {
                "name": event_anchor["event_name"],
                "window": {
                    "start_date": event_anchor["temporal_window"]["start_date"],
                    "end_date": event_anchor["temporal_window"]["end_date"],
                },
                "reported_locations": event_anchor["locked_event_anchor"]["event_location"],
            },
            "conditions": {
                "thick_peat": bool(re.search(r"Thick peat", folded_html, flags=re.I)),
                "el_nino_dry_weather": bool(re.search(r"El Nino", folded_html, flags=re.I)),
                "economic_development": bool(re.search(r"economic development", folded_html, flags=re.I)),
                "peat_fires_co": bool(re.search(r"carbon monoxide.*abundant in peat fires", folded_text, flags=re.I)),
            },
            "co_signal": {
                "usual_surface_ppb": usual_co_ppb,
                "peak_surface_borneo_ppb_nearly": peak_co_ppb,
                "peak_to_usual_multiplier": co_multiplier,
            },
            "vertical_transport": {
                "calipso_plume_km": calipso_plume_km,
                "airs_co_km": airs_co_km,
                "mls_co_km": mls_co_km,
                "mls_to_calipso_ratio": height_ratio,
            },
            "context_checks": {
                "rainfall_totals_secondary": True,
                "rainfall_diagnostic_window_note": (
                    "Open-Meteo point rainfall totals cover 2015-08-01 to 2015-09-15; gridded rainfall "
                    "statistics are package event-accumulated diagnostics and remain secondary to the CO ledger."
                ),
                "rainfall_mm": rain_context,
                "burn_perimeter_from_dnbr": "not_established",
                "dnbr_pre_count": dnbr["counts"]["pre_count"],
                "dnbr_post_count": dnbr["counts"]["post_count"],
                "dnbr_status": dnbr["status"],
            },
            "image_pair": remote_sensing,
            "computed_interpretation": (
                "The event should be scored as a peat-smoke carbon monoxide signal, with rainfall and dNBR treated "
                "as secondary checks rather than the primary ledger."
            ),
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": HIDDEN_INPUTS,
            "notes": "Values are regenerated from local CSX-179 inputs and rounded only for the compact ledger.",
        },
    }

    OUTPUT_PATH.write_text(json.dumps(computed, indent=2, ensure_ascii=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
